import { Pool } from "pg";

export interface Device {
  id: string;
  siteId: string;
  model: string;
  firmware: string;
}

export interface Site {
  id: string;
  name: string;
  timezone: string;
}

export interface LatestReading {
  deviceId: string;
  recordedAt: Date;
  temperatureC: number;
  batteryPct: number;
}

export class FleetRepository {
  constructor(private readonly pool: Pool) {}

  async devicesForAccount(accountId: string): Promise<Device[]> {
    const { rows } = await this.pool.query(
      `SELECT id, site_id AS "siteId", model, firmware_version AS firmware
         FROM devices WHERE account_id = $1 AND decommissioned_at IS NULL`,
      [accountId],
    );
    return rows;
  }

  async latestReadings(deviceIds: string[]): Promise<Map<string, LatestReading>> {
    if (deviceIds.length === 0) return new Map();
    const { rows } = await this.pool.query(
      `SELECT DISTINCT ON (device_id) device_id AS "deviceId", recorded_at AS "recordedAt",
              temperature_c AS "temperatureC", battery_pct AS "batteryPct"
         FROM readings
        WHERE device_id = ANY($1) AND recorded_at > now() - interval '24 hours'
        ORDER BY device_id, recorded_at DESC`,
      [deviceIds],
    );
    return new Map(rows.map((r: LatestReading) => [r.deviceId, r]));
  }

  async siteById(siteId: string): Promise<Site | null> {
    const { rows } = await this.pool.query(
      `SELECT id, name, timezone FROM sites WHERE id = $1`,
      [siteId],
    );
    return rows[0] ?? null;
  }
}

import { FleetRepository, Site } from "./fleetRepository";

export interface DeviceTile {
  deviceId: string;
  model: string;
  siteName: string;
  siteTimezone: string;
  online: boolean;
  temperatureC: number | null;
  lowBattery: boolean;
}

const OFFLINE_AFTER_MS = 15 * 60 * 1000;
const LOW_BATTERY_PCT = 20;

export class FleetDashboard {
  constructor(private readonly repo: FleetRepository) {}

  async tiles(accountId: string, now: Date = new Date()): Promise<DeviceTile[]> {
    const devices = await this.repo.devicesForAccount(accountId);
    const readings = await this.repo.latestReadings(devices.map((d) => d.id));
    const siteCache = new Map<string, Site | null>();

    const tiles: DeviceTile[] = [];
    for (const device of devices) {
      let site = siteCache.get(device.siteId);
      if (site === undefined) {
        site = await this.repo.siteById(device.siteId);
      }
      const reading = readings.get(device.id);
      const online =
        reading !== undefined && now.getTime() - reading.recordedAt.getTime() < OFFLINE_AFTER_MS;
      tiles.push({
        deviceId: device.id,
        model: device.model,
        siteName: site?.name ?? "Unassigned",
        siteTimezone: site?.timezone ?? "UTC",
        online,
        temperatureC: reading ? reading.temperatureC : null,
        lowBattery: reading !== undefined && reading.batteryPct < LOW_BATTERY_PCT,
      });
    }
    return tiles.sort((a, b) => Number(a.online) - Number(b.online));
  }
}
